tailwind:
/* Arbitrary value: exactly the CSS gradient, any Tailwind v4 project. */
bg-[linear-gradient(90deg_in_oklch_longer_hue,#ff0000,#00ff00)]

/* Native utilities (two or three stops). bg-linear-<angle> interpolates in OKLAB by default in Tailwind v4; the modifier pins the space. */
bg-linear-90/longer from-[#ff0000] to-[#00ff00]

/* Theme variable: use as class "bg-gradient". */
@theme {
  --background-image-gradient: linear-gradient(90deg in oklch longer hue, #ff0000, #00ff00);
}

/* Custom utility: use as class "bg-gradient". */
@utility bg-gradient {
  background-image: linear-gradient(90deg in oklch longer hue, #ff0000, #00ff00);
}

scss:
$gradient-angle: 90deg;
$gradient-color-1: #ff0000;
$gradient-color-2: #00ff00;

$gradient: linear-gradient(
  $gradient-angle in oklch longer hue,
  $gradient-color-1,
  $gradient-color-2
);

// Usage: background: $gradient;

css-variables:
:root {
  --gradient-angle: 90deg;
  --gradient-color-1: #ff0000;
  --gradient-color-2: #00ff00;
  --gradient: linear-gradient(var(--gradient-angle) in oklch longer hue, var(--gradient-color-1), var(--gradient-color-2));
}

/* Usage: background: var(--gradient); */

